360	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
361	// project directories if needed.
362	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
363		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
364		if err != nil {
365			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
366		}
367		// Only call PrepareTranscript when the file already exists — it flushes
368		// in-progress writes, but can't conjure a file that was never started.
369		// This avoids agents like Cursor polling for 3s on non-existent files
370		// during auto-detection.
371		if _, statErr := os.Stat(transcriptPath); statErr == nil {
372			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
373				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
374					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
375				}
376			}
377			return transcriptPath, nil
378		}
379		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
380		if searchErr == nil {
381			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
382			return found, nil
383		}
384		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
385		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
386	}
387	
388	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
389	// transcript resolution succeeds for the given session ID.
390	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
391		for _, name := range agent.List() {
392			if name == skip {
393				continue
394			}
395			ag, err := agent.Get(name)
396			if err != nil {
397				continue
398			}
399			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
400			if resolveErr != nil {
401				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
402				continue
403			}
404			return ag, path, nil
405		}
406		return nil, "", errors.New("transcript not found for any registered agent")
407	}
