409	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
410	// When force is true, it amends without prompting.
411	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
412		shortHash := headCommit.Hash.String()[:7]
413		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
414	
415		// Skip amending if this exact checkpoint ID is already in the commit.
416		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
417			if existing.String() == checkpointIDStr {
418				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
419				return nil
420			}
421		}
422	
423		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
424	
425		amend := true
426		if !force {
427			if !interactive.CanPromptInteractively() {
428				// Non-interactive: can't prompt, print trailer for manual use.
429				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
430				return nil
431			}
432			form := NewAccessibleForm(
433				huh.NewGroup(
434					huh.NewConfirm().
435						Title("Amend the last commit in this branch?").
436						Affirmative("Y").
437						Negative("n").
438						Value(&amend),
439				),
440			)
441			if err := form.Run(); err != nil {
442				return fmt.Errorf("prompt failed: %w", err)
443			}
444		}
445	
446		if !amend {
447			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
448			return nil
449		}
450	
451		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
452	
453		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
454		if output, err := cmd.CombinedOutput(); err != nil {
455			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
456		}
457	
458		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
459		return nil
460	}
