93	// runStop is the main logic for the stop command.
94	func runStop(ctx context.Context, cmd *cobra.Command, sessionID string, all, force bool) error {
95		// --session path: stop a specific session by explicit ID (no worktree scoping).
96		if sessionID != "" {
97			return runStopSession(ctx, cmd, sessionID, force)
98		}
99	
100		// List all session states
101		states, err := strategy.ListSessionStates(ctx)
102		if err != nil {
103			return fmt.Errorf("failed to list sessions: %w", err)
104		}
105	
106		activeSessions := filterActiveSessions(states)
107	
108		// --all path: stop all active sessions across all worktrees.
109		if all {
110			return runStopAll(ctx, cmd, activeSessions, force)
111		}
112	
113		// No-flags path: show all active sessions across all worktrees.
114		// This aligns with `entire status` which displays sessions globally.
115		// Users see worktree labels in the multi-select to make informed choices.
116		if len(activeSessions) == 0 {
117			fmt.Fprintln(cmd.OutOrStdout(), "No active sessions.")
118			return nil
119		}
120	
121		// One active session: confirm + stop.
122		if len(activeSessions) == 1 {
123			return runStopSession(ctx, cmd, activeSessions[0].SessionID, force)
124		}
125	
126		// Multiple active sessions: show TUI multi-select.
127		return runStopMultiSelect(ctx, cmd, activeSessions, force)
128	}
