147	// sessionWorktreeLabel returns the worktree display label for a session.
148	// Uses WorktreeID if available, falls back to the last path component of
149	// WorktreePath, or "(unknown)" for empty values (legacy sessions without
150	// worktree tracking). Matches status.go's unknownPlaceholder convention.
151	func sessionWorktreeLabel(s *strategy.SessionState) string {
152		if s.WorktreeID != "" {
153			return s.WorktreeID
154		}
155		if s.WorktreePath != "" {
156			return filepath.Base(s.WorktreePath)
157		}
158		return unknownPlaceholder
