191	func runSessionList(ctx context.Context, cmd *cobra.Command) error {
192		states, err := strategy.ListSessionStates(ctx)
193		if err != nil {
194			return fmt.Errorf("failed to list sessions: %w", err)
195		}
196	
197		var filtered []*strategy.SessionState
198		for _, s := range states {
199			if s != nil {
200				filtered = append(filtered, s)
201			}
202		}
203	
204		w := cmd.OutOrStdout()
205	
206		if len(filtered) == 0 {
207			fmt.Fprintln(w, "No sessions.")
208			return nil
209		}
210	
211		// Sort by StartedAt descending (newest first)
212		sort.Slice(filtered, func(i, j int) bool {
213			return filtered[i].StartedAt.After(filtered[j].StartedAt)
214		})
215	
216		sty := newStatusStyles(w)
217	
218		fmt.Fprintln(w, sty.sectionRule("Sessions", sty.width))
219		fmt.Fprintln(w)
220	
221		for _, s := range filtered {
222			writeSessionCard(w, s, sty)
223		}
224	
225		// Footer
226		fmt.Fprintln(w, sty.horizontalRule(sty.width))
227		if len(filtered) == 1 {
228			fmt.Fprintln(w, sty.render(sty.dim, "1 session"))
229		} else {
230			fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("%d sessions", len(filtered))))
231		}
232		fmt.Fprintln(w)
233	
234		return nil
235	}
