237	// writeSessionCard renders a single session in status-style card format.
238	func writeSessionCard(w io.Writer, s *strategy.SessionState, sty statusStyles) {
239		agentLabel := string(s.AgentType)
240		if agentLabel == "" {
241			agentLabel = "(unknown)"
242		}
243		wt := sessionWorktreeLabel(s)
244	
245		// Line 1: Agent · Model · worktree · session <id> [· checkpoint <id>]
246		fmt.Fprint(w, sty.render(sty.agent, agentLabel))
247		if s.ModelName != "" {
248			fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), sty.render(sty.dim, s.ModelName))
249		}
250		fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), wt)
251		fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), s.SessionID)
252		if s.LastCheckpointID != "" {
253			fmt.Fprintf(w, " %s checkpoint %s", sty.render(sty.dim, "·"), string(s.LastCheckpointID))
254		}
255		fmt.Fprintln(w)
256	
257		// Line 2: > "prompt" (truncated)
258		if s.LastPrompt != "" {
259			prompt := stringutil.TruncateRunes(s.LastPrompt, 60, "...")
260			fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
261		}
262	
263		// Line 3: status · started X ago · active X ago · tokens X.Xk
264		var stats []string
265		stats = append(stats, sessionPhaseLabel(s))
266		stats = append(stats, "started "+timeAgo(s.StartedAt))
267		if s.LastInteractionTime != nil && s.LastInteractionTime.Sub(s.StartedAt) > time.Minute {
268			stats = append(stats, activeTimeDisplay(s.LastInteractionTime))
269		}
270		if t := totalTokens(s.TokenUsage); t > 0 {
271			stats = append(stats, "tokens "+formatTokenCount(t))
272		}
273		statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
274		fmt.Fprintln(w, sty.render(sty.dim, statsLine))
275		fmt.Fprintln(w)
276	}
