464	// runStopSession stops a single session by ID, with optional confirmation.
465	func runStopSession(ctx context.Context, cmd *cobra.Command, sessionID string, force bool) error {
466		state, err := strategy.LoadSessionState(ctx, sessionID)
467		if err != nil {
