471			cmd.SilenceUsage = true
472			fmt.Fprintln(cmd.ErrOrStderr(), "Session not found.")
473			return NewSilentError(fmt.Errorf("session not found: %s", sessionID))
474		}
475	
476		if state.Phase == session.PhaseEnded || state.EndedAt != nil {
477			fmt.Fprintf(cmd.OutOrStdout(), "Session %s is already stopped.\n", sessionID)
478			return nil
479		}
480	
481		if !force {
