486						Title(fmt.Sprintf("Stop session %s?", sessionID)).
487						Value(&confirmed),
488				),
489			)
490			if err := form.Run(); err != nil {
491				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
492			}
493			if !confirmed {
494				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
495				return nil
496			}
497		}
498	
499		return stopSessionAndPrint(ctx, cmd, state)
