516				),
517			)
518			if err := form.Run(); err != nil {
519				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
520			}
521			if !confirmed {
522				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
523				return nil
524			}
525		}
