531	func runStopMultiSelect(ctx context.Context, cmd *cobra.Command, activeSessions []*strategy.SessionState, force bool) error {
532		options := make([]huh.Option[string], len(activeSessions))
533		for i, s := range activeSessions {
534			wt := sessionWorktreeLabel(s)
535			label := fmt.Sprintf("%s · %s · %s", s.AgentType, wt, s.SessionID)
536			if s.LastPrompt != "" {
537				prompt := stringutil.TruncateRunes(s.LastPrompt, 40, "...")
538				label = fmt.Sprintf("%s · %q", label, prompt)
539			}
540			options[i] = huh.NewOption(label, s.SessionID)
541		}
542	
543		var selectedIDs []string
544		form := NewAccessibleForm(
545			huh.NewGroup(
546				huh.NewMultiSelect[string]().
547					Title("Select sessions to stop").
548					Description("Use space to select, enter to confirm.").
549					Options(options...).
550					Value(&selectedIDs),
551			),
552		)
553		if err := form.Run(); err != nil {
554			return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
555		}
556	
557		if len(selectedIDs) == 0 {
558			fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
559			return nil
560		}
561	
562		// Build a map for quick lookup
563		stateByID := make(map[string]*strategy.SessionState, len(activeSessions))
564		for _, s := range activeSessions {
565			stateByID[s.SessionID] = s
566		}
567	
568		// Confirm only if not forcing
569		if !force {
570			var confirmed bool
571			form := NewAccessibleForm(
572				huh.NewGroup(
573					huh.NewConfirm().
574						Title(fmt.Sprintf("Stop %d session(s)?", len(selectedIDs))).
575						Value(&confirmed),
576				),
577			)
578			if err := form.Run(); err != nil {
579				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
580			}
581			if !confirmed {
582				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
583				return nil
584			}
585		}
586	
587		var toStop []*strategy.SessionState
588		for _, id := range selectedIDs {
589			if s, ok := stateByID[id]; ok {
590				toStop = append(toStop, s)
591			} else {
592				// Session was concurrently stopped between form render and confirmation.
593				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: session %s no longer found, skipping.\n", id)
594			}
595		}
596		if len(toStop) == 0 {
597			fmt.Fprintln(cmd.OutOrStdout(), "No sessions to stop.")
598			return nil
599		}
600		return stopSelectedSessions(ctx, cmd, toStop)
601	}
602	
603	// stopSelectedSessions stops each session in the list and prints a result line.
604	// Errors from individual sessions are accumulated so a single failure does not
605	// prevent remaining sessions from being stopped. Each failure is printed to stderr
606	// immediately so the user knows which sessions could not be stopped.
607	func stopSelectedSessions(ctx context.Context, cmd *cobra.Command, sessions []*strategy.SessionState) error {
608		var errs []error
609		for _, s := range sessions {
610			if err := stopSessionAndPrint(ctx, cmd, s); err != nil {
611				fmt.Fprintf(cmd.ErrOrStderr(), "✗ %v\n", err)
612				errs = append(errs, err)
613			}
614		}
615		return errors.Join(errs...)
616	}
617	
618	// stopSessionAndPrint stops a session and prints a summary line.
619	// Fields needed for output are read before calling markSessionEnded because
620	// markSessionEnded loads and operates on its own copy of the session state by ID —
621	// it does not update the caller's state pointer.
622	func stopSessionAndPrint(ctx context.Context, cmd *cobra.Command, state *strategy.SessionState) error {
623		sessionID := state.SessionID
624		lastCheckpointID := state.LastCheckpointID
625		stepCount := state.StepCount
626	
627		if err := markSessionEnded(ctx, nil, sessionID); err != nil {
628			return fmt.Errorf("failed to stop session %s: %w", sessionID, err)
629		}
630	
631		fmt.Fprintf(cmd.OutOrStdout(), "✓ Session %s stopped.\n", sessionID)
632		switch {
633		case lastCheckpointID != "":
634			fmt.Fprintf(cmd.OutOrStdout(), "  Checkpoint: %s\n", lastCheckpointID)
635		case stepCount > 0:
636			fmt.Fprintln(cmd.OutOrStdout(), "  Work will be captured in your next checkpoint.")
637		default:
638			fmt.Fprintln(cmd.OutOrStdout(), "  No work recorded.")
639		}
640		return nil
641	}
