```go
import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// ListSessionsInDir enumerates *.jsonl files in dir and returns one RepoSession
// per file, sorted by ModifiedAt descending. If dir does not exist, returns an
// empty slice and nil error (this is normal for agents the user has never run).
// If limit > 0, the result is truncated to that length.
func ListSessionsInDir(dir string, limit int) ([]RepoSession, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}

	rows := make([]RepoSession, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasSuffix(name, ".jsonl") {
			continue
		}
		info, infoErr := e.Info()
		if infoErr != nil {
			// Entry disappeared between ReadDir and Info. Skip.
			continue
		}
		rows = append(rows, RepoSession{
			SessionID:      strings.TrimSuffix(name, ".jsonl"),
			TranscriptPath: filepath.Join(dir, name),
			ModifiedAt:     info.ModTime(),
		})
	}

	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].ModifiedAt.Equal(rows[j].ModifiedAt) {
			return rows[i].SessionID < rows[j].SessionID
		}
		return rows[i].ModifiedAt.After(rows[j].ModifiedAt)
	})

	if limit > 0 && len(rows) > limit {
		rows = rows[:limit]
	}
	return rows, nil
}
```

