```go
import (
	"context"
	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// ListRepoSessions enumerates Codex sessions globally, then filters to those
// recorded in repoRoot via the session_meta.payload.cwd field.
// Over-fetches 2×limit to compensate for cross-repo sessions at the top of the
// global dir (heavy Codex users in multiple repos).
func (c *CodexAgent) ListRepoSessions(_ context.Context, repoRoot string, limit int) ([]agent.RepoSession, error) {
	dir, err := c.GetSessionDir(repoRoot) // ignores repoRoot; returns global dir
	if err != nil {
		return nil, err
	}

	fetch := limit * 2
	if limit == 0 {
		fetch = 0 // unbounded
	}
	all, err := agent.ListSessionsInDir(dir, fetch)
	if err != nil {
		return nil, err
	}

	filtered := make([]agent.RepoSession, 0, limit)
	for _, s := range all {
		cwd, cwdErr := ReadCWDFromTranscript(s.TranscriptPath)
		if cwdErr != nil {
			// Malformed or missing CWD — drop the row; safer than including
			// a potentially-wrong-repo session.
			continue
		}
		if cwd != repoRoot {
			continue
		}
		filtered = append(filtered, s)
		if limit > 0 && len(filtered) >= limit {
			break
		}
	}
	return filtered, nil
}
```

> **Note:** Codex's `GetSessionDir` may have nested `YYYY/MM/DD/` subdirectories (see `codex/codex.go:77-86`). `ListSessionsInDir` as written only reads one directory level — if Codex actually nests, either (a) the generic helper must be updated to walk recursively, or (b) the Codex wrapper does its own walk before calling the helper. Check how real Codex layouts look and adjust. The safer path is extending the generic helper with an optional recursive flag.

