import (
	"context"
	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// untrackedRow pairs a RepoSession with the agent that produced it.
type untrackedRow struct {
	Agent   types.AgentName
	Session agent.RepoSession
}

// gatherUntrackedSessions walks all registered agents and collects on-disk
// sessions that aren't already in trackedIDs. Errors from any one agent are
// logged and collected but do not abort the walk.
func gatherUntrackedSessions(
	ctx context.Context,
	repoRoot string,
	limit int,
	trackedIDs map[string]struct{},
	onlyAgent types.AgentName, // empty = all agents
) ([]untrackedRow, []agentError) {
	var rows []untrackedRow
	var errs []agentError

	for _, name := range agent.List() {
		if onlyAgent != "" && name != onlyAgent {
			continue
		}
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		sl, ok := agent.AsSessionLister(ag)
		if !ok {
			continue
		}
		sessions, err := sl.ListRepoSessions(ctx, repoRoot, limit)
		if err != nil {
			logging.Debug(ctx, "SessionLister failed", "agent", string(name), "error", err)
			errs = append(errs, agentError{Agent: name, Err: err})
			continue
		}
		for _, s := range sessions {
			if _, already := trackedIDs[s.SessionID]; already {
				continue
			}
			rows = append(rows, untrackedRow{Agent: name, Session: s})
		}
	}
	return rows, errs
}

type agentError struct {
	Agent types.AgentName
	Err   error
}
```

