package agent

import (
	"context"
	"time"
)

// SessionLister is implemented by agents that can enumerate their on-disk
// sessions for a given repo root. The picker uses this to discover sessions
// Entire does not have state files for.
type SessionLister interface {
	// ListRepoSessions returns on-disk sessions relevant to repoRoot.
	// limit caps the number of rows; 0 means no cap.
	// Implementations must return rows sorted by ModifiedAt descending.
	ListRepoSessions(ctx context.Context, repoRoot string, limit int) ([]RepoSession, error)
}

// RepoSession is the minimum a picker row needs beyond what tracked state already provides.
type RepoSession struct {
	SessionID      string
	TranscriptPath string
	ModifiedAt     time.Time
}
```

