// AsSessionLister returns the agent as SessionLister if it both implements the
// interface and (for CapabilityDeclarer agents) has declared the capability.
func AsSessionLister(ag Agent) (SessionLister, bool) { //nolint:ireturn // type-assertion helper must return interface
	if ag == nil {
		return nil, false
	}
	sl, ok := ag.(SessionLister)
	if !ok {
		return nil, false
	}
	if cd, ok := ag.(CapabilityDeclarer); ok {
		return sl, cd.DeclaredCapabilities().SessionLister
	}
	return sl, true
}
