```go
import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// ListSessionsInDir walks dir recursively, collecting one RepoSession per
// *.jsonl file. Returns rows sorted by ModifiedAt descending with a stable
// tiebreaker by SessionID ascending. Returns (nil, nil) if dir is missing.
// If limit > 0, the result is truncated to that length.
func ListSessionsInDir(dir string, limit int) ([]RepoSession, error) {
	var rows []RepoSession

	walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			// A missing root is not an error for our purposes.
			if errors.Is(err, fs.ErrNotExist) && path == dir {
				return fs.SkipAll
			}
			return err
		}
		if d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".jsonl") {
			return nil
		}
		info, infoErr := d.Info()
		if infoErr != nil {
			// Race: entry disappeared. Skip.
			return nil
		}
		rows = append(rows, RepoSession{
			SessionID:      strings.TrimSuffix(d.Name(), ".jsonl"),
			TranscriptPath: path,
			ModifiedAt:     info.ModTime(),
		})
		return nil
	})
	if walkErr != nil && !errors.Is(walkErr, fs.ErrNotExist) {
		// An ErrNotExist at the root is normal; deeper ErrNotExist during walk
		// is fine too (race). Any other error propagates.
		var pathErr *os.PathError
		if !errors.As(walkErr, &pathErr) {
			return nil, walkErr
		}
	}

	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].ModifiedAt.Equal(rows[j].ModifiedAt) {
			return rows[i].SessionID < rows[j].SessionID
		}
		return rows[i].ModifiedAt.After(rows[j].ModifiedAt)
	})

	if limit > 0 && len(rows) > limit {
		rows = rows[:limit]
	}
	return rows, nil
}
```

