```go
import (
	"context"
	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// ListRepoSessions enumerates Codex sessions globally, then filters to those
// recorded in repoRoot via the session_meta.payload.cwd field. Over-fetches
// 2×limit to compensate for cross-repo sessions at the top of the global dir.
func (c *CodexAgent) ListRepoSessions(_ context.Context, repoRoot string, limit int) ([]agent.RepoSession, error) {
	dir, err := c.GetSessionDir(repoRoot) // repoPath is ignored — returns global ~/.codex/sessions
	if err != nil {
		return nil, err
	}

	fetch := limit * 2
	if limit == 0 {
		fetch = 0 // unbounded
	}
	all, err := agent.ListSessionsInDir(dir, fetch)
	if err != nil {
		return nil, err
	}

	filtered := make([]agent.RepoSession, 0, limit)
	for _, s := range all {
		cwd, cwdErr := ReadCWDFromTranscript(s.TranscriptPath)
		if cwdErr != nil {
			continue // safer to drop than include a potentially-wrong-repo session
		}
		if cwd != repoRoot {
			continue
		}
		filtered = append(filtered, s)
		if limit > 0 && len(filtered) >= limit {
			break
		}
	}
	return filtered, nil
}
```

