import (
	"context"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// namedLister pairs an agent name with its SessionLister. Passed in explicitly
// (rather than discovered via the registry) so tests can inject fakes.
type namedLister struct {
	name   types.AgentName
	lister agent.SessionLister
}

// untrackedRow pairs a RepoSession with the agent that produced it.
type untrackedRow struct {
	Agent   types.AgentName
	Session agent.RepoSession
}

type agentError struct {
	Agent types.AgentName
	Err   error
}

// discoverListers walks the agent registry and returns every agent that
// implements SessionLister. Production callers use this; tests inject fakes
// via namedLister directly.
func discoverListers() []namedLister {
	out := []namedLister{}
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		if sl, ok := agent.AsSessionLister(ag); ok {
			out = append(out, namedLister{name: name, lister: sl})
		}
	}
	return out
}

// gatherUntrackedSessions invokes each agent's SessionLister and returns rows
// not already in trackedIDs. Errors from any one agent are logged + collected
// but do not abort the walk. If onlyAgent is non-empty, other agents are skipped.
func gatherUntrackedSessions(
	ctx context.Context,
	agents []namedLister,
	repoRoot string,
	limit int,
	trackedIDs map[string]struct{},
	onlyAgent types.AgentName,
) ([]untrackedRow, []agentError) {
	var rows []untrackedRow
	var errs []agentError

	for _, a := range agents {
		if onlyAgent != "" && a.name != onlyAgent {
			continue
		}
		sessions, err := a.lister.ListRepoSessions(ctx, repoRoot, limit)
		if err != nil {
			logging.Debug(ctx, "SessionLister failed", "agent", string(a.name), "error", err)
			errs = append(errs, agentError{Agent: a.name, Err: err})
			continue
		}
		for _, s := range sessions {
			if _, already := trackedIDs[s.SessionID]; already {
				continue
			}
			rows = append(rows, untrackedRow{Agent: a.name, Session: s})
		}
	}
	return rows, errs
}
```

