import (
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/stringutil"
)

// renderRowLabel produces the one-line string shown in the picker.
func renderRowLabel(r pickerRow) string {
	var parts []string
	parts = append(parts, string(r.agentName()))
	parts = append(parts, shortID(r.sessionID()))

	if r.isTracked() && r.tracked.LastPrompt != "" {
		parts = append(parts, fmt.Sprintf("%q", stringutil.TruncateRunes(r.tracked.LastPrompt, 60, "...")))
	}
	parts = append(parts, agoString(r.modifiedAt()))
	parts = append(parts, trackedStatusLabel(r))
	return strings.Join(parts, "  ")
}

func (r pickerRow) agentName() types.AgentName {
	if r.isTracked() {
		return types.AgentName(r.tracked.AgentType)
	}
	return r.untracked.Agent
}

func shortID(id string) string {
	if len(id) < 7 {
		return id
	}
	return id[:7]
}

func agoString(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Hour:
		return fmt.Sprintf("%dm ago", int(d.Minutes()))
	case d < 24*time.Hour:
		return fmt.Sprintf("%dh ago", int(d.Hours()))
	default:
		return fmt.Sprintf("%dd ago", int(d.Hours()/24))
	}
}

func trackedStatusLabel(r pickerRow) string {
	if !r.isTracked() {
		return "[untracked]"
	}
	if r.tracked.LastCheckpointID != "" {
		return fmt.Sprintf("[tracked → %s]", shortID(string(r.tracked.LastCheckpointID)))
	}
	return "[tracked]"
}
```

