import (
	"github.com/charmbracelet/huh"
)

// huhOption is a flat pair used by the form runner indirection.
type huhOption struct {
	Label string
	Value string // stringified row key, e.g. sessionID
}

// runSelect is a package variable so tests can swap in a stub. Production
// implementation shows a huh.Select wrapped in NewAccessibleForm.
var runSelect = func(title string, options []huhOption) (string, error) {
	huhOpts := make([]huh.Option[string], len(options))
	for i, o := range options {
		huhOpts[i] = huh.NewOption(o.Label, o.Value)
	}
	var choice string
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title(title).
				Options(huhOpts...).
				Value(&choice),
		),
	)
	if err := form.Run(); err != nil {
		return "", err
	}
	return choice, nil
}

// selectFromPickerRows shows the session select and returns the chosen row
// (nil if cancelled).
func selectFromPickerRows(title string, rows []pickerRow) (*pickerRow, error) {
	if len(rows) == 0 {
		return nil, nil
	}
	opts := make([]huhOption, len(rows))
	for i, r := range rows {
		opts[i] = huhOption{Label: renderRowLabel(r), Value: r.sessionID()}
	}
	chosen, err := runSelect(title, opts)
	if err != nil {
		return nil, err
	}
	if chosen == "" {
		return nil, nil
	}
	for i := range rows {
		if rows[i].sessionID() == chosen {
			return &rows[i], nil
		}
	}
	return nil, nil
}
