import (
	"io"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// pickerResult is what runPicker returns on a successful pick.
type pickerResult struct {
	SessionID string
	Agent     types.AgentName
}

// runPicker runs the full picker flow. Returns (nil, nil) if the user cancels.
// onlyAgent narrows the scope (skipping the agent-filter step if non-empty).
func runPicker(ctx context.Context, w io.Writer, onlyAgent types.AgentName, limit int) (*pickerResult, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve repo root: %w", err)
	}
	worktreeID, worktreePath, err := resolveCurrentWorktree(ctx, repoRoot)
	if err != nil {
		return nil, err
	}

	// Tracked source.
	allStates, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return nil, fmt.Errorf("list session states: %w", err)
	}
	tracked := filterTrackedSessionsToWorktree(allStates, worktreeID, worktreePath)
	trackedIDs := make(map[string]struct{}, len(tracked))
	for _, s := range tracked {
		trackedIDs[s.SessionID] = struct{}{}
	}

	// Decide whether to show the agent-filter step.
	accessible := os.Getenv("ACCESSIBLE") != ""
	chosenAgent := onlyAgent
	if chosenAgent == "" && !accessible {
		listers := discoverListers()
		names := make([]types.AgentName, len(listers))
		for i, l := range listers {
			names[i] = l.name
		}
		picked, err := selectAgentFilter(names)
		if err != nil {
			return nil, err
		}
		chosenAgent = picked
	}

	// Untracked source (filtered by chosenAgent when set).
	untracked, agentErrs := gatherUntrackedSessions(ctx, discoverListers(), repoRoot, limit, trackedIDs, chosenAgent)
	for _, e := range agentErrs {
		fmt.Fprintf(w, "Warning: %s: %v\n", e.Agent, e.Err)
	}

	rows, truncated := mergePickerRows(tracked, untracked, limit)
	if len(rows) == 0 {
		if chosenAgent != "" {
			fmt.Fprintf(w, "No %s sessions found for this repo.\n", chosenAgent)
		} else {
			fmt.Fprintln(w, "No sessions found for this repo. Run `entire attach <session-id>` directly if you have a session ID.")
		}
		return nil, nil
	}

	title := "Select a session to attach:"
	if truncated > 0 {
		title = fmt.Sprintf("%s (showing %d; %d more — raise --limit to see all)", title, len(rows), truncated)
	}
	picked, err := selectFromPickerRows(title, rows)
	if err != nil {
		return nil, err
	}
	if picked == nil {
		return nil, nil
	}
	return &pickerResult{SessionID: picked.sessionID(), Agent: picked.agentName()}, nil
}

