package codex

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

// ReadCWDFromTranscript opens a Codex transcript and extracts the recorded CWD
// from the first session_meta line. Returns an error if the line is absent,
// malformed, or does not contain a cwd field.
func ReadCWDFromTranscript(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	const maxLine = 1 << 20 // 1 MiB — Codex rollouts can exceed the default 64KB.
	scanner.Buffer(make([]byte, 0, 64*1024), maxLine)

	if !scanner.Scan() {
		if err := scanner.Err(); err != nil {
			return "", fmt.Errorf("read first line: %w", err)
		}
		return "", errors.New("transcript is empty")
	}

	var envelope struct {
		Type    string `json:"type"`
		Payload struct {
			CWD string `json:"cwd"`
		} `json:"payload"`
	}
	if err := json.Unmarshal(scanner.Bytes(), &envelope); err != nil {
		return "", fmt.Errorf("parse first line: %w", err)
	}
	if envelope.Type != "session_meta" {
		return "", fmt.Errorf("first line type = %q, want session_meta", envelope.Type)
	}
	if envelope.Payload.CWD == "" {
		return "", errors.New("session_meta.payload.cwd is empty or missing")
	}
	return envelope.Payload.CWD, nil
}
