package copilotcli

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

// ReadCWDFromTranscript opens a Copilot CLI transcript and extracts the
// recorded CWD from the first session.start event's data.context.cwd field.
func ReadCWDFromTranscript(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	const maxLine = 1 << 20
	scanner.Buffer(make([]byte, 0, 64*1024), maxLine)

	if !scanner.Scan() {
		if err := scanner.Err(); err != nil {
			return "", fmt.Errorf("read first line: %w", err)
		}
		return "", errors.New("transcript is empty")
	}

	var envelope struct {
		Type string `json:"type"`
		Data struct {
			Context struct {
				CWD string `json:"cwd"`
			} `json:"context"`
		} `json:"data"`
	}
	if err := json.Unmarshal(scanner.Bytes(), &envelope); err != nil {
		return "", fmt.Errorf("parse first line: %w", err)
	}
	if envelope.Type != "session.start" {
		return "", fmt.Errorf("first line type = %q, want session.start", envelope.Type)
	}
	if envelope.Data.Context.CWD == "" {
		return "", errors.New("session.start.data.context.cwd is empty or missing")
	}
	return envelope.Data.Context.CWD, nil
}
