package cli

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/entireio/cli/cmd/entire/cli/agent/copilotcli"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// cwdReader is the shape of per-agent first-line CWD extractors (Codex/Copilot).
type cwdReader func(transcriptPath string) (string, error)

// listSessionsForAgent enumerates the on-disk sessions of a single agent for
// the given repo. Five agents use the generic directory walker directly; Codex
// and Copilot filter a global dir down to sessions that recorded this repo as
// their CWD in the transcript's first message.
func listSessionsForAgent(ctx context.Context, ag agent.Agent, repoRoot string, limit int) ([]agent.RepoSession, error) {
	dir, err := ag.GetSessionDir(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve session dir for %s: %w", ag.Name(), err)
	}

	switch ag.Type() {
	case agent.AgentTypeCodex:
		return listWithCWDFilter(ctx, dir, repoRoot, limit, codex.ReadCWDFromTranscript)
	case agent.AgentTypeCopilot:
		return listWithCWDFilter(ctx, dir, repoRoot, limit, copilotcli.ReadCWDFromTranscript)
	default:
		return agent.ListSessionsInDir(dir, limit)
	}
}

// listWithCWDFilter walks dir, over-fetches 2×limit to compensate for
// cross-repo sessions at the top of a global dir, then keeps only rows whose
// transcripts recorded the current repoRoot as their CWD.
func listWithCWDFilter(ctx context.Context, dir, repoRoot string, limit int, readCWD cwdReader) ([]agent.RepoSession, error) {
	fetch := limit * 2
	if limit == 0 {
		fetch = 0 // unbounded
	}
	all, err := agent.ListSessionsInDir(dir, fetch)
	if err != nil {
		return nil, err
	}

	filtered := make([]agent.RepoSession, 0, limit)
	for _, s := range all {
		cwd, cwdErr := readCWD(s.TranscriptPath)
		if cwdErr != nil {
			logging.Debug(ctx, "CWD read failed — dropping row", "path", s.TranscriptPath, "error", cwdErr)
			continue
		}
		if cwd != repoRoot {
			continue
		}
		filtered = append(filtered, s)
		if limit > 0 && len(filtered) >= limit {
			break
		}
	}
	return filtered, nil
}
