import "github.com/entireio/cli/cmd/entire/cli/strategy"

// filterTrackedSessionsToWorktree returns the subset of states scoped to the
// current worktree. Matches on WorktreeID first; falls back to WorktreePath for
// legacy sessions that predate the WorktreeID field.
func filterTrackedSessionsToWorktree(states []*strategy.SessionState, worktreeID, worktreePath string) []*strategy.SessionState {
	out := make([]*strategy.SessionState, 0, len(states))
	for _, s := range states {
		if s == nil {
			continue
		}
		switch {
		case s.WorktreeID != "" && s.WorktreeID == worktreeID:
			out = append(out, s)
		case s.WorktreeID == "" && s.WorktreePath != "" && s.WorktreePath == worktreePath:
			out = append(out, s)
		}
	}
	return out
}
