import "github.com/entireio/cli/cmd/entire/cli/agent/types"

// untrackedRow pairs a RepoSession with the agent that produced it.
type untrackedRow struct {
	Agent   types.AgentName
	Session agent.RepoSession
}

type agentError struct {
	Agent types.AgentName
	Err   error
}

// discoverAgents returns every registered agent. A package variable so tests
// can swap in a fake list.
var discoverAgents = func() []agent.Agent {
	names := agent.List()
	out := make([]agent.Agent, 0, len(names))
	for _, name := range names {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		out = append(out, ag)
	}
	return out
}

// gatherUntrackedSessions iterates over agents, calls listSessionsForAgent on
// each (subject to onlyAgent filter), and returns rows whose session IDs are
// not already in trackedIDs. Errors from any one agent are logged + collected.
func gatherUntrackedSessions(
	ctx context.Context,
	agents []agent.Agent,
	repoRoot string,
	limit int,
	trackedIDs map[string]struct{},
	onlyAgent types.AgentName,
) ([]untrackedRow, []agentError) {
	var rows []untrackedRow
	var errs []agentError

	for _, ag := range agents {
		name := types.AgentName(ag.Name())
		if onlyAgent != "" && name != onlyAgent {
			continue
		}
		sessions, err := listSessionsForAgent(ctx, ag, repoRoot, limit)
		if err != nil {
			logging.Debug(ctx, "listSessionsForAgent failed", "agent", string(name), "error", err)
			errs = append(errs, agentError{Agent: name, Err: err})
			continue
		}
		for _, s := range sessions {
			if _, already := trackedIDs[s.SessionID]; already {
				continue
			}
			rows = append(rows, untrackedRow{Agent: name, Session: s})
		}
	}
	return rows, errs
}
