```go
import "sort"

// pickerRow is a union of a tracked session state and an untracked on-disk row.
// Exactly one of tracked/untracked is non-nil.
type pickerRow struct {
	tracked   *strategy.SessionState
	untracked *untrackedRow
}

func (r pickerRow) isTracked() bool { return r.tracked != nil }

func (r pickerRow) sessionID() string {
	if r.tracked != nil {
		return r.tracked.SessionID
	}
	return r.untracked.Session.SessionID
}

func (r pickerRow) modifiedAt() time.Time {
	if r.tracked != nil {
		if r.tracked.LastInteractionTime != nil {
			return *r.tracked.LastInteractionTime
		}
		return r.tracked.StartedAt
	}
	return r.untracked.Session.ModifiedAt
}

func (r pickerRow) agentName() types.AgentName {
	if r.isTracked() {
		return types.AgentName(r.tracked.AgentType)
	}
	return r.untracked.Agent
}

// mergePickerRows combines tracked + untracked rows. Tracked wins on session-ID
// conflict. Output is sorted by modifiedAt desc, stable-tiebreak by session ID asc.
// If limit > 0, truncates the output and returns the count dropped.
func mergePickerRows(tracked []*strategy.SessionState, untracked []untrackedRow, limit int) ([]pickerRow, int) {
	seen := make(map[string]struct{}, len(tracked))
	rows := make([]pickerRow, 0, len(tracked)+len(untracked))

	for _, s := range tracked {
		if s == nil {
			continue
		}
		seen[s.SessionID] = struct{}{}
		rows = append(rows, pickerRow{tracked: s})
	}
	for i := range untracked {
		u := &untracked[i]
		if _, dup := seen[u.Session.SessionID]; dup {
			continue
		}
		rows = append(rows, pickerRow{untracked: u})
	}

	sort.SliceStable(rows, func(i, j int) bool {
		ti, tj := rows[i].modifiedAt(), rows[j].modifiedAt()
		if ti.Equal(tj) {
			return rows[i].sessionID() < rows[j].sessionID()
		}
		return ti.After(tj)
	})

	truncated := 0
	if limit > 0 && len(rows) > limit {
		truncated = len(rows) - limit
		rows = rows[:limit]
	}
	return rows, truncated
}
```

