// selectAgentFilter shows the first step of the iterative picker.
// Returns empty for "All agents".
func selectAgentFilter(agents []types.AgentName) (types.AgentName, error) {
	opts := make([]huhOption, 0, len(agents)+1)
	opts = append(opts, huhOption{Label: "All agents", Value: ""})
	for _, a := range agents {
		opts = append(opts, huhOption{Label: string(a), Value: string(a)})
	}
	chosen, err := runSelect("Filter sessions by agent:", opts)
	if err != nil {
		return "", err
	}
	return types.AgentName(chosen), nil
}
