```go
package agent

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type RepoSession struct {
	SessionID      string
	TranscriptPath string
	ModifiedAt     time.Time
}

// ListSessionsInDir walks dir recursively, collecting *.jsonl files as
// RepoSessions sorted by ModifiedAt desc with stable tiebreak by SessionID asc.
// Missing dir → (nil, nil).
func ListSessionsInDir(dir string, limit int) ([]RepoSession, error) {
	var rows []RepoSession
	walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) && path == dir {
				return fs.SkipAll
			}
			return err
		}
		if d.IsDir() || !strings.HasSuffix(d.Name(), ".jsonl") {
			return nil
		}
		info, infoErr := d.Info()
		if infoErr != nil {
			return nil
		}
		rows = append(rows, RepoSession{
			SessionID:      strings.TrimSuffix(d.Name(), ".jsonl"),
			TranscriptPath: path,
			ModifiedAt:     info.ModTime(),
		})
		return nil
	})
	if walkErr != nil && !errors.Is(walkErr, fs.ErrNotExist) {
		var pathErr *os.PathError
		if !errors.As(walkErr, &pathErr) {
			return nil, walkErr
		}
	}
	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].ModifiedAt.Equal(rows[j].ModifiedAt) {
			return rows[i].SessionID < rows[j].SessionID
		}
		return rows[i].ModifiedAt.After(rows[j].ModifiedAt)
	})
	if limit > 0 && len(rows) > limit {
		rows = rows[:limit]
	}
	return rows, nil
}
```

