package codex

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

// ReadCWDFromTranscript extracts session_meta.payload.cwd from the first line of a Codex transcript.
func ReadCWDFromTranscript(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 1<<20) // 1 MiB cap

	if !scanner.Scan() {
		if err := scanner.Err(); err != nil {
			return "", fmt.Errorf("read first line: %w", err)
		}
		return "", errors.New("transcript is empty")
	}
	var env struct {
		Type    string `json:"type"`
		Payload struct {
			CWD string `json:"cwd"`
		} `json:"payload"`
	}
	if err := json.Unmarshal(scanner.Bytes(), &env); err != nil {
		return "", fmt.Errorf("parse first line: %w", err)
	}
	if env.Type != "session_meta" {
		return "", fmt.Errorf("first line type = %q, want session_meta", env.Type)
	}
	if env.Payload.CWD == "" {
		return "", errors.New("session_meta.payload.cwd is empty or missing")
	}
	return env.Payload.CWD, nil
}
