```go
func newAttachCmd() *cobra.Command {
	var (
		force     bool
		agentFlag string
		limit     int
	)
	cmd := &cobra.Command{
		Use:   "attach [<session-id>]",
		Short: "Attach an existing agent session",
		// Update the long-description's leading line to mention the picker.
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}
			if len(args) == 1 {
				if cmd.Flags().Changed("limit") {
					cmd.SilenceUsage = true
					return fmt.Errorf("--limit is not valid with a positional session ID")
				}
				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], types.AgentName(agentFlag), force)
			}
			var scopedAgent types.AgentName
			if cmd.Flags().Changed("agent") {
				scopedAgent = types.AgentName(agentFlag)
			}
			return runAttachWithPicker(cmd.Context(), cmd.OutOrStdout(), scopedAgent, limit, force)
		},
	}
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, codex, cursor, copilot-cli, factoryai-droid)")
	cmd.Flags().IntVar(&limit, "limit", 50, "Cap per-agent enumeration in the picker (only used when no session ID is given)")
	return cmd
}

var runAttachWithPicker = func(ctx context.Context, w io.Writer, agentName types.AgentName, limit int, force bool) error {
	result, err := runPicker(ctx, w, agentName, limit)
	if err != nil {
		return err
	}
	if result == nil {
		fmt.Fprintln(w, "Cancelled.")
		return nil
	}
	return runAttach(ctx, w, result.SessionID, result.Agent, force)
}
```

